methods.description:
Use this only before wpdb::prepare() or esc_sql(). Reversing the order is very bad for security.

Example Prepared Statement:

    $wild = '%';
    $find = 'only 43% of planets';
    $like = $wild . $wpdb->esc_like( $find ) . $wild;
    $sql  = $wpdb->prepare( "SELECT * FROM $wpdb->posts WHERE post_content LIKE %s", $like );

Example Escape Chain:

    $sql  = esc_sql( $wpdb->esc_like( $input ) );

Examples:

    $wpdb->insert(
        'table',
        array(
            'column1' => 'foo',
            'column2' => 'bar',
        )
    );
    $wpdb->insert(
        'table',
        array(
            'column1' => 'foo',
            'column2' => 1337,
        ),
        array(
            '%s',
            '%d',
        )
    );

Examples:

    $wpdb->update(
        'table',
        array(
            'column1' => 'foo',
            'column2' => 'bar',
        ),
        array(
            'ID' => 1,
        )
    );
    $wpdb->update(
        'table',
        array(
            'column1' => 'foo',
            'column2' => 1337,
        ),
        array(
            'ID' => 1,
        ),
        array(
            '%s',
            '%d',
        ),
        array(
            '%d',
        )
    );

Examples:

    $wpdb->delete(
        'table',
        array(
            'ID' => 1,
        )
    );
    $wpdb->delete(
        'table',
        array(
            'ID' => 1,
        ),
        array(
            '%d',
        )
    );

